"""
Evolve the composite dipole with the finite-regulator rotated NLO generator.

Apply Eq. (16) to the generator a*K0+a^2*K1 and retain through a^2 before solving the resulting nonlinear ODE. Evolve the supplied composite initial state for the nonnegative elapsed rapidity. Every chain contraction uses factorized adjacent dipoles. Accuracy should support absolute state error 2e-8 on the stated finite test domains.

Returns
-------
return result  # ndarray, shape (n,n), evolved composite dipole, dimensionless.
"""

# =============================================================================
# FUNCTION SIGNATURE (shown to the LLM)
# =============================================================================

def evolve_rotated_dipole(s: "np.ndarray", one: "np.ndarray", two: "np.ndarray", alpha: float, rapidity: float) -> "np.ndarray":
    """s : ndarray, shape (n,n), dimensionless dipole values, row = first endpoint. Algebraic cases may be nonsymmetric.
    one : ndarray, shape (3,n,n,n), weighted single-emission kernels in emission_kernels order.
    two : ndarray, shape (2,n,n,n,n), weighted pair_kernels output.
    alpha : nonnegative float, dimensionless fixed a.
    rapidity : nonnegative float, dimensionless evolution interval.

    Returns
    -------
    ndarray, shape (n,n), evolved composite dipole, dimensionless.
    Inputs must be finite. Invalid dimensions, scales, or prescribed domains raise ValueError. 
    """
    return result

# =============================================================================
# GOLD SOLUTION
# =============================================================================

import numpy as np

def _state(s,one):
    import numpy as np
    s=np.asarray(s);one=np.asarray(one)
    if s.ndim!=2:raise ValueError('State must be a matrix.')
    n=len(s)
    if s.shape!=(n,n) or one.shape!=(3,n,n,n) or not np.all(np.isfinite(s)) or not np.all(np.isfinite(one)):
        raise ValueError('Incompatible state or emission kernels.')
    return s,one


def _oracle_evolve_rotated_dipole(s: "np.ndarray", one: "np.ndarray", two: "np.ndarray", alpha: float, rapidity: float) -> "np.ndarray":
    """Finite-regulator NLO evolution with the unintegrated operator commutator."""
    import numpy as np
    from scipy.integrate import solve_ivp
    s,one=_state(s,one);n=len(s)
    if alpha<0 or rapidity<0 or not np.isfinite(alpha+rapidity):raise ValueError('Invalid evolution parameters.')
    if alpha==0 or rapidity==0:return s.copy()
    def _rhs(y,flat):
        state=flat.reshape(n,n)
        return (alpha*_oracle_dipole_fields(state,one)[0]+alpha**2*(_oracle_nlo_action(state,one,two)+_oracle_scheme_commutator(state,one))).ravel()
    sol=solve_ivp(_rhs,[0,rapidity],s.ravel(),method='DOP853',rtol=2e-11,atol=2e-13)
    if not sol.success or not np.all(np.isfinite(sol.y[:,-1])):raise ValueError('Evolution failed.')
    return sol.y[:,-1].reshape(n,n)

